-- NGBCL platform — M0 foundation: identity, permissions, refresh tokens, tournaments, audit log.
-- Conventions: UUID keys (generated by the application, v7), timestamptz in UTC,
-- status columns instead of deletes, CHECK constraints for domain invariants.

-- ---------------------------------------------------------------------------
-- Identity & RBAC (SRS §2, §6.1 users / roles / user_roles)
-- ---------------------------------------------------------------------------
CREATE TABLE roles (
    code        varchar(40)  PRIMARY KEY,
    name        varchar(80)  NOT NULL,
    description varchar(255)
);

CREATE TABLE role_permissions (
    role_code   varchar(40) NOT NULL REFERENCES roles (code),
    permission  varchar(40) NOT NULL,
    PRIMARY KEY (role_code, permission)
);

CREATE TABLE users (
    id             uuid         PRIMARY KEY,
    email          varchar(254) NOT NULL,
    display_name   varchar(120) NOT NULL,
    password_hash  varchar(255) NOT NULL,
    status         varchar(20)  NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'DISABLED')),
    last_login_at  timestamptz,
    created_at     timestamptz  NOT NULL,
    updated_at     timestamptz  NOT NULL,
    version        bigint       NOT NULL DEFAULT 0,
    CONSTRAINT users_email_lowercase CHECK (email = lower(email))
);
CREATE UNIQUE INDEX users_email_uq ON users (email);

CREATE TABLE user_roles (
    user_id    uuid        NOT NULL REFERENCES users (id),
    role_code  varchar(40) NOT NULL REFERENCES roles (code),
    PRIMARY KEY (user_id, role_code)
);

-- Rotating refresh tokens; only a SHA-256 hash is stored. A reused (already rotated)
-- token revokes its whole family (theft detection).
CREATE TABLE refresh_tokens (
    id          uuid        PRIMARY KEY,
    user_id     uuid        NOT NULL REFERENCES users (id),
    family_id   uuid        NOT NULL,
    token_hash  varchar(64)    NOT NULL,
    issued_at   timestamptz NOT NULL,
    expires_at  timestamptz NOT NULL,
    rotated_at  timestamptz,
    revoked_at  timestamptz,
    user_agent  varchar(255),
    ip_hash     varchar(64)
);
CREATE UNIQUE INDEX refresh_tokens_hash_uq ON refresh_tokens (token_hash);
CREATE INDEX refresh_tokens_family_idx ON refresh_tokens (family_id);
CREATE INDEX refresh_tokens_user_idx ON refresh_tokens (user_id);

-- ---------------------------------------------------------------------------
-- Tournaments (SRS §4.1 TRN-001..006). Settings tables arrive in M1.
-- ---------------------------------------------------------------------------
CREATE TABLE tournaments (
    id           uuid         PRIMARY KEY,
    slug         varchar(60)  NOT NULL,
    name         varchar(160) NOT NULL,
    short_name   varchar(40)  NOT NULL,
    edition      varchar(20)  NOT NULL,
    description  text,
    starts_on    date,
    ends_on      date,
    venue        varchar(200),
    city         varchar(80),
    status       varchar(20)  NOT NULL DEFAULT 'DRAFT'
                 CHECK (status IN ('DRAFT', 'UPCOMING', 'ACTIVE', 'COMPLETED', 'ARCHIVED')),
    timezone     varchar(60)  NOT NULL DEFAULT 'Asia/Colombo',
    currency     varchar(3)     NOT NULL DEFAULT 'LKR',
    is_current   boolean      NOT NULL DEFAULT false,
    created_at   timestamptz  NOT NULL,
    updated_at   timestamptz  NOT NULL,
    version      bigint       NOT NULL DEFAULT 0,
    CONSTRAINT tournaments_dates_ck CHECK (ends_on IS NULL OR starts_on IS NULL OR ends_on >= starts_on)
);
CREATE UNIQUE INDEX tournaments_slug_uq ON tournaments (slug);
-- Exactly one "current" edition drives the public site until edition 2.0 adds a switcher.
CREATE UNIQUE INDEX tournaments_one_current_uq ON tournaments (is_current) WHERE is_current;

-- ---------------------------------------------------------------------------
-- Audit log (SRS REP-005/006, AUC-034, MAT-009). Insert-only by convention;
-- production DB role for the app should have no UPDATE/DELETE grant on this table.
-- ---------------------------------------------------------------------------
CREATE TABLE audit_logs (
    id             uuid         PRIMARY KEY,
    occurred_at    timestamptz  NOT NULL,
    actor_id       uuid         REFERENCES users (id),
    actor_label    varchar(160) NOT NULL,
    action         varchar(80)  NOT NULL,
    entity_type    varchar(60)  NOT NULL,
    entity_id      varchar(80),
    tournament_id  uuid         REFERENCES tournaments (id),
    before_state   jsonb,
    after_state    jsonb,
    reason         varchar(500),
    ip_hash        varchar(64)
);
CREATE INDEX audit_logs_entity_idx ON audit_logs (entity_type, entity_id);
CREATE INDEX audit_logs_actor_idx ON audit_logs (actor_id);
CREATE INDEX audit_logs_time_idx ON audit_logs (occurred_at DESC);

